#!/usr/bin/env sh
# Чистая функция: значение на stdin -> "key" | "password" | "empty" на stdout.
#
# Ни сети, ни файлов, ни записи входа куда бы то ни было: единственный вывод —
# одно слово. Форма определяется по префиксу, а не попыткой подключиться, чтобы
# прогон тратил ровно одну попытку входа (см. design.md).
set -eu

value="$(cat)"
trimmed="$(printf '%s' "$value" | sed -e 's/^[[:space:]]*//')"

case "$trimmed" in
    # Пустое значение формы не имеет. Отдельный ответ, а не «пароль»: иначе
    # незаполненный секрет уйдёт в попытку входа заведомо пустым паролем.
    '') printf 'empty\n' ;;
    '-----BEGIN'*) printf 'key\n' ;;
    *) printf 'password\n' ;;
esac
